  125	    /**
  126	     * The candidate lists in the order the planner tries them. A warehouse about to overflow stops
  127	     * that planet producing, so its pass runs across every planet before any routine step; a full
  128	     * warehouse (E7) is a spend signal and comes next; then the routine economy: energy before it
  129	     * throttles, the chain's facilities, the fastest-paying mine. Public so a read-out explains a
  130	     * planet with the same lists the decision used.
  131	     *
  132	     * @return array<string, callable(PlanetService): list<BuildCandidate>>
  133	     */
  134	    public function passes(AiProfile $profile): array
  135	    {
  136	        return [
  137	            // A planet holding no defence while a sibling already stands a wall is past the
  138	            // account's opening with a sibling walled everywhere else: the facilities the wall
  139	            // itself waits on come before the economy, so the planet is not left naked behind a
  140	            // stock it is busy spending (QUAL-003). The step is the same shape as a wall order: a
  141	            // saving the economy is holding back does not veto it, because a planet with no wall is
  142	            // the state the account is fixing, not a step it chooses between (QUAL-003).
  143	            'wall' => fn (PlanetService $planet): array => $this->facilityChain->wallPending($planet),
  144	            'storage' => fn (PlanetService $planet): array => $this->economyUpgrades->storage($planet, $profile),
  145	            'surplus' => fn (PlanetService $planet): array => $this->economyUpgrades->spendSurplus($planet, $profile),
  146	            'routine' => fn (PlanetService $planet): array => [
  147	                ...$this->energyCapacity->pending($planet),
  148	                ...$this->facilityChain->pending($planet),
  149	                ...$this->economyUpgrades->storageForPrice($planet, $profile),
  150	                ...$this->economyUpgrades->production($planet, $profile),
  151	            ],
  152	        ];
  153	    }
  154	
  155	    /**
  156	     * The build queue and the lab run side by side, so a planet's building and the account's one
  157	     * technology are separate steps: a planet whose best candidate is a technology still builds.
  158	     *
  159	     * @param array<int|string, QueueableBuilding|QueueableResearch> $steps
  160	     * @param callable(PlanetService): list<BuildCandidate> $pass
  161	     * @return array<int|string, QueueableBuilding|QueueableResearch>
  162	     */
  163	    private function withStep(array $steps, PlanetService $planet, AiProfile $profile, callable $pass, ?SavingsGoal $goal, bool $wall = false): array
  164	    {
  165	        $candidates = $pass($planet);
  166	        $isResearch = static fn (BuildCandidate $candidate): bool => ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research;
  167	
  168	        // The candidate list is in priority order, so whichever queue its first entry belongs to is tried first.
  169	        $queues = [$planet->getPlanetId() => false, self::LAB_STEP => true];
  170	        if ($candidates !== [] && $isResearch($candidates[0])) {
  171	            $queues = array_reverse($queues, true);
  172	        }
  173	
  174	        foreach ($queues as $key => $research) {
  175	            if (isset($steps[$key])) {
  176	                continue;
  177	            }
  178	
  179	            $step = $this->firstQueueable($planet, $profile, array_values(array_filter($candidates, static fn (BuildCandidate $candidate): bool => $isResearch($candidate) === $research)), $wall ? null : $goal);
  180	            if ($step !== null) {
  181	                $steps[$key] = $step;
  182	            }
  183	        }
  184	
  185	        return $steps;
  186	    }
  187	
  188	    /**
  189	     * The first candidate this planet can actually queue, or null when none of them is legal.
  190	     *
  191	     * @param list<BuildCandidate> $candidates
  192	     */
  193	    private function firstQueueable(PlanetService $planet, AiProfile $profile, array $candidates, ?SavingsGoal $goal): QueueableBuilding|QueueableResearch|null
  194	    {
  195	        foreach ($candidates as $candidate) {
  196	            if (!$this->canSpendFor($planet, $goal, $candidate)) {
  197	                continue;
  198	            }
  199	
  200	            // Which queue takes a step is the host's object type, not this module's opinion: the
  201	            // chain hands over prerequisites, and a technology among them is research.
  202	            if (ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research) {
  203	                $research = $this->queueableResearch($planet, $candidate);
  204	                if ($research === null) {
  205	                    continue;
  206	                }
  207	
  208	                return $research;
  209	            }
  210	
  211	            $planetId = $planet->getPlanetId();
  212	            if (!$this->canQueue($planet, $candidate)) {
  213	                continue;
  214	            }
